// Map your form's fields here. Works with most form tools that POST JSON.
const cfg = $('Config').first().json;
return $input.all().map(i => {
  const b = i.json.body || i.json;
  const lead = {
    name: (b.name || [b.first_name, b.last_name].filter(Boolean).join(' ') || '').trim(),
    email: (b.email || '').trim().toLowerCase(),
    phone: (b.phone || '').trim(),
    company: (b.company || '').trim(),
    message: (b.message || b.notes || '').trim(),
    source: b.source || 'website form',
  };
  const request = {
    model: cfg.openai_model,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: `You qualify inbound leads for ${cfg.business_name}. Reply with JSON: {"score": 1-10, "reason": "one sentence", "summary": "one sentence"}. 10 = ready to buy, clear need, good fit. 1 = spam or no fit.` },
      { role: 'user', content: JSON.stringify(lead) },
    ],
  };
  return { json: { ...lead, request } };
});

